body {
  --seojae-readable-width: 684px;
  --seojae-custom-line-height: 1.9;
  --seojae-custom-paragraph-spacing: 0.95rem;
  --seojae-footnote-scale: 0.86em;
  --seojae-line-height: 1.9;
  --seojae-paragraph-spacing: 0.95rem;
  --font-text-theme: "Times New Roman", "Seojae Myeongjo", "Nanum Myeongjo", "나눔명조", "Noto Serif CJK KR", serif;
  --font-text-size: 18px;
  --line-height-normal: var(--seojae-line-height);
  --line-height-tight: 1.5;
  --p-spacing: var(--seojae-paragraph-spacing);
  --heading-spacing: 2.1em;
  --file-line-width: var(--seojae-readable-width);
  --file-margins: 40px 44px 64px;

  --h1-font: var(--font-text);
  --h2-font: var(--font-text);
  --h3-font: var(--font-text);
  --h4-font: var(--font-text);
  --h5-font: var(--font-text);
  --h6-font: var(--font-text);
  --h1-size: 1.65em;
  --h2-size: 1.35em;
  --h3-size: 1.16em;
  --h4-size: 1.05em;
  --h5-size: 1em;
  --h6-size: 0.95em;
  --h1-weight: 700;
  --h2-weight: 700;
  --h3-weight: 700;
  --h4-weight: 700;
  --h5-weight: 700;
  --h6-weight: 700;
  --h1-line-height: 1.55;
  --h2-line-height: 1.6;
  --h3-line-height: 1.65;
  --h4-line-height: 1.7;
  --h5-line-height: 1.7;
  --h6-line-height: 1.7;
  --h1-color: var(--text-normal);
  --h2-color: var(--text-normal);
  --h3-color: var(--text-normal);
  --h4-color: var(--text-normal);
  --h5-color: var(--text-normal);
  --h6-color: var(--text-muted);
  --bold-weight: 700;
  --bold-color: var(--text-normal);
  --italic-color: var(--text-normal);
  --inline-title-font: var(--font-text);
  --inline-title-size: 1.65em;
  --inline-title-weight: 700;
  --inline-title-line-height: 1.55;

  --link-decoration: underline;
  --link-decoration-hover: underline;
  --link-external-decoration: underline;
  --link-external-decoration-hover: underline;
  --link-unresolved-opacity: 1;
  --blockquote-border-thickness: 2px;
  --blockquote-font-style: normal;
  --blockquote-color: var(--text-normal);
  --table-text-size: 0.94em;
  --table-header-font: var(--font-text);
  --table-header-weight: 700;
  --table-header-color: var(--text-normal);
  --table-line-height: 1.75;
  --table-cell-vertical-alignment: top;
  --table-border-width: 1px;
  --table-header-border-width: 1px;
  --table-column-max-width: 36em;
  --code-size: 0.85em;
  --code-radius: 4px;
  --code-normal: var(--text-normal);
  --list-spacing: 0.3em;
  --footnote-size: var(--seojae-footnote-scale);
  --callout-radius: 4px;
  --callout-border-width: 1px;
  --callout-border-opacity: 0.22;
  --callout-title-weight: 600;
  --tag-radius: 4px;
  --tag-size: 0.82em;
  --nav-item-size: 13px;
  --nav-item-weight-active: 600;
  --tab-font-size: 13px;
  --metadata-label-font-size: 13px;
  --metadata-input-font-size: 13px;
  --input-radius: 5px;
  --button-radius: 5px;
}

body.seojae-density-standard {
  --seojae-line-height: 1.9;
  --seojae-paragraph-spacing: 0.95rem;
}

body.seojae-density-compact {
  --seojae-line-height: 1.75;
  --seojae-paragraph-spacing: 0.7rem;
}

body.seojae-density-relaxed {
  --seojae-line-height: 2.05;
  --seojae-paragraph-spacing: 1.2rem;
}

body.seojae-density-custom {
  --seojae-line-height: var(--seojae-custom-line-height);
  --seojae-paragraph-spacing: var(--seojae-custom-paragraph-spacing);
}

