/* Native font-size settings remain authoritative. UI and code keep their fonts. */
.markdown-rendered,
.markdown-source-view.mod-cm6 .cm-scroller {
  font-kerning: normal;
}

/* Reading view only: do not alter CodeMirror's measured line geometry or IME. */
.markdown-rendered :is(p, li, blockquote, td, th) {
  word-break: keep-all;
  overflow-wrap: anywhere;
}

.markdown-rendered :is(a, .internal-link) {
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

.markdown-rendered blockquote {
  padding: 0.45em 1.1em;
  margin-inline: 0;
  border-radius: 0 4px 4px 0;
}

.markdown-rendered blockquote > :first-child {
  margin-top: 0;
}

.markdown-rendered blockquote > :last-child {
  margin-bottom: 0;
}

.markdown-rendered :is(th, td) {
  padding: 0.55em 0.85em;
}

.markdown-rendered .el-table {
  overflow-x: auto;
}

.markdown-rendered .footnotes {
  margin-top: 2.5em;
  padding-top: 0.6em;
  border-top: 1px solid var(--hr-color);
  color: var(--text-muted);
  font-size: var(--seojae-footnote-scale);
}

.markdown-rendered .footnotes hr {
  display: none;
}

.markdown-rendered .footnotes :is(p, li) {
  line-height: 1.8;
}

/* Opt-in bibliography layout for notes with `cssclasses: seojae-references`. */
.markdown-preview-view.seojae-references :is(.markdown-preview-sizer, .markdown-preview-section) > .el-p > p,
.markdown-preview-view.seojae-references .csl-bib-body > .csl-entry,
.markdown-preview-view.seojae-references :is(p, li, .csl-entry).hanging-indent,
.markdown-preview-view.seojae-references .hanging-indent > :is(p, .csl-entry) {
  padding-inline-start: 2em;
  text-indent: -2em;
  word-break: normal;
  overflow-wrap: anywhere;
}

.markdown-rendered .callout-title {
  font-family: var(--font-interface);
  font-size: 0.88em;
}

.markdown-rendered .callout-content > :last-child {
  margin-bottom: 0;
}

.markdown-rendered :is(a, button, input):focus-visible {
  outline: 2px solid var(--interactive-accent);
  outline-offset: 3px;
}

@media screen and (max-width: 600px) {
  body {
    --file-margins: 24px 20px 40px;
  }
}

/* A readable draft preset; institutional submission requirements may differ. */
@page {
  size: A4;
  margin: 25mm 22mm;
}

@media print {
  body.theme-light,
  body.theme-dark {
    color-scheme: light;
    --background-primary: #ffffff;
    --background-primary-alt: #ffffff;
    --background-secondary: #ffffff;
    --text-normal: #000000;
    --text-muted: #333333;
    --text-faint: #444444;
    --text-accent: #000000;
    --text-accent-hover: #000000;
    --link-color: #000000;
    --link-external-color: #000000;
    --link-unresolved-color: #333333;
    --tag-color: #333333;
    --tag-color-hover: #000000;
    --tag-background: transparent;
    --tag-background-hover: transparent;
    --h6-color: #333333;
    --bold-color: #000000;
    --italic-color: #000000;
    --blockquote-color: #000000;
    --blockquote-border-color: #777777;
    --blockquote-background-color: transparent;
    --code-normal: #000000;
    --code-comment: #444444;
    --code-function: #000000;
    --code-important: #000000;
    --code-keyword: #000000;
    --code-operator: #000000;
    --code-property: #000000;
    --code-punctuation: #333333;
    --code-string: #333333;
    --code-tag: #000000;
    --code-value: #333333;
    --code-background: #f4f4f4;
    --table-border-color: #888888;
    --table-header-color: #000000;
    --table-header-background: #f0f0f0;
    --table-row-alt-background: transparent;
    --hr-color: #aaaaaa;
    --font-text-size: 11pt;
    --line-height-normal: 1.8;
    --p-spacing: 0.95rem;
    --file-line-width: 100%;
    --file-margins: 0;
  }

  .markdown-rendered {
    font-size: 11pt;
    line-height: 1.8;
    color: #000000;
    background: #ffffff;
  }

  .markdown-rendered :is(h1, h2, h3, h4, h5, h6) {
    break-after: avoid;
  }

  .markdown-rendered :is(p, li) {
    orphans: 3;
    widows: 3;
  }

  .markdown-rendered :is(tr, img, svg) {
    break-inside: avoid;
  }

  .markdown-rendered thead {
    display: table-header-group;
  }

  .markdown-rendered table {
    width: 100%;
    max-width: 100%;
    table-layout: fixed;
  }

  .markdown-rendered .el-table {
    overflow: visible;
  }

  .markdown-rendered :is(td, th, a) {
    overflow-wrap: anywhere;
  }

  .markdown-rendered pre {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  .markdown-rendered .callout {
    background: transparent;
    border-color: #999999;
  }

  .markdown-rendered .callout-title {
    color: #333333;
  }
}


